{
  "root": "main",
  "state": {
    "salesData": [
      { "month": "Jan", "orders": 120, "revenue": 3600, "arpo": 30.0 },
      { "month": "Feb", "orders": 140, "revenue": 4100, "arpo": 29.29 },
      { "month": "Mar", "orders": 135, "revenue": 4050, "arpo": 30.0 },
      { "month": "Apr", "orders": 170, "revenue": 5200, "arpo": 30.59 },
      { "month": "May", "orders": 190, "revenue": 5900, "arpo": 31.05 },
      { "month": "Jun", "orders": 165, "revenue": 5300, "arpo": 32.12 }
    ]
  },
  "elements": {
    "main": { "type": "Stack", "props": { "direction": "vertical", "gap": "md", "padding": 16 }, "children": ["title", "table", "insights", "actions", "sources"] },
    "title": { "type": "Text", "props": { "text": "Monthly Sales Dashboard Overview", "variant": "h1" }, "children": [] },
    "table": { "type": "Table", "props": { "domain": "generic", "preferredPresentation": "table", "statePath": "/salesData", "columns": [{ "key": "month", "label": "Month" }, { "key": "orders", "label": "Orders" }, { "key": "revenue", "label": "Revenue" }, { "key": "arpo", "label": "Revenue per Order" }] }, "children": [] },
    "insights": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["insightTitle", "insight1", "insight2", "insight3"] },
    "insightTitle": { "type": "Text", "props": { "text": "Key Insights", "variant": "h2" }, "children": [] },
    "insight1": { "type": "Text", "props": { "text": "Growth trend is strong overall: revenue rose from 3600 in January to 5300 in June." }, "children": [] },
    "insight2": { "type": "Text", "props": { "text": "May was the peak month with 190 orders and 5900 revenue." }, "children": [] },
    "insight3": { "type": "Text", "props": { "text": "Order quality improved: revenue per order increased from 30.00 to 32.12." }, "children": [] },
    "actions": { "type": "Stack", "props": { "direction": "horizontal", "gap": "md" }, "children": ["btn1", "btn2"] },
    "btn1": { "type": "Button", "props": { "label": "Build Revenue Chart", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.google.com/search?q=how+to+build+a+line+chart+for+monthly+revenue" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Compare Dashboard KPIs", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.google.com/search?q=dashboard+KPI+examples+for+sales+analytics" } } } }, "children": [] },
    "sources": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["sourceTitle", "s1", "s2"] },
    "sourceTitle": { "type": "Text", "props": { "text": "Sources", "variant": "h3" }, "children": [] },
    "s1": { "type": "Button", "props": { "label": "Chart selection guidance", "variant": "borderless", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.nngroup.com/articles/charts-data-visualization/" } } } }, "children": [] },
    "s2": { "type": "Button", "props": { "label": "Dashboard KPI best practices", "variant": "borderless", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.tableau.com/learn/articles/dashboard-design-best-practices" } } } }, "children": [] }
  }
}
